def point_type(name, fields, srid_map):
    """
    Args:
        name (str): The name of the Point subclass
        fields (List[str]): A list of field names
        srid_map (Dict[str, int]): A dictionary mapping field names to SRIDs
    """

    class Point(NamedTuple):
        x: float
        y: float

        _srid = 0

        def __init__(self, x, y, srid=0):
            self.x = x
            self.y = y
            self._srid = srid

        def __hash__(self):
            return hash((self.x, self.y, self._srid))

        def __eq__(self, other):
            if not isinstance(other, Point):
                return False
            return (self.x, self.y, self._srid) == (other.x, other.y, other._srid)

        @property
        def as_py_dict(self):
            return {
                field: getattr(self, field) for field in fields
            }

        @classmethod
        def from_py_dict(cls, d):
            return cls(
                x=d["x"],
                y=d["y"],
                srid=d.get("srid", 0),
            )

        def __str__(self):
            return f"Point({self.x},{self.y},{self._srid})"

    Point.__name__ = name
    for field in fields:
        Point._fields = field
        Point._field_names = fields
        Point._srid_map = srid_map

    return Point

