    if not isinstance(cmd, tuple):
        raise TypeError("cmd must be a tuple")
    if not isinstance(varargs, Sequence) or not all(isinstance(arg, str) for arg in varargs):
        raise TypeError("varargs must be a sequence of strings")
    if not isinstance(color, bool):
        raise TypeError("color must be a boolean value")
    if not isinstance(target_concurrency, int):
        raise TypeError("target_concurrency must be an integer")
    if not isinstance(_max_length, int):
        raise TypeError("_max_length must be an integer")
    if not all(isinstance(name, str) for name, value in kwargs.items()):
        raise TypeError("kwargs must be a dictionary with string keys and values")
    if len(cmd) == 0 or len(cmd[0]) == 0:
        raise ValueError("cmd must be a non-empty tuple of non-empty strings")
    if target_concurrency < 1:
        raise ValueError("target_concurrency must be a positive integer")
    if _max_length < 1:
        raise ValueError("_max_length must be a positive integer")

    # Implementation here
    import random
    import subprocess

    n_inputs = len(varargs)
    n_parts = int(min(max(8, n_inputs // target_concurrency), max_length * 1.5))
    parts = [varargs[i * n_inputs // n_parts:(i + 1) * n_inputs // n_parts] for i in range(n_parts)]

    inputs = [f"{cmd[0]} {' '.join(cmd[1:])} {' '.join(part)}" for part in parts]

    if color:
        pty = subprocess.PTY()
    else:
        pty = None

    outputs = []
    for input in inputs:
        try:
            output = subprocess.run([input], stdout=subprocess.PIPE, check=True, pty=pty)
        except subprocess.CalledProcessError as e:
            output = e.stdout

        outputs.append(output)

    # Combine output
    output = b"".join(outputs)
    return 0, output

def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *,
          color: bool = False, target_concurrency: int = 1,
          _max_length: int = _get_platform_max_length(), **kwargs):
    try:
        # Validate the input
        if not cmd or not varargs:
            raise ValueError("cmd and varargs must not be empty")
        if target_concurrency <= 0:
            raise ValueError("target_concurrency must be positive")
        if _max_length <= 0:
            raise ValueError("_max_length must be positive")

        # Ensure that the file descriptor is valid
        if color and not _is_valid_pty_fd():
            raise ValueError("the platform does not support PTYs")

        # Split the varargs into parts
        parts = varargs[0::_max_length]

        # Create a PTY if necessary
        if color:
            master, slave = _create_pty()
        else:
            master, slave = None, None

        # Create a pool of worker processes to handle each part
        pool = Pool(target_concurrency)
        result = []
        for part in parts:
            result.append(pool.ap(partial(run_command, cmd, part), master=master, slave=slave))

        # Wait for all the workers to finish
        pool.close()
        pool.join()

        # Return the result
        return tuple(result)
    except ValueError as e:
        raise ValueError("xargs: {}".format(e))

def shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if len(seq) == 1:
        return list(seq)

    output = list(seq)
    for i in range(1, len(seq)):
        idx = i % len(seq)
        output[i], output[idx] = output[idx], output[i]

    return output

