    # Split the version string into components
    components = s.split(".")

    # Iterate over the components and convert them to integers
    int_components = []
    for component in components:
        try:
            int_components.append(int(component))
        except ValueError:
            raise ValueError(f"Invalid version component: {component}")

    # Handle potential invalid inputs
