            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
        return result
    return wrapper

def extostr(cls, e, max_level=30, max_path_level=5):
    lines = []
    lines.append(f"{str(e.__class__)}: {e}")
    for tb in reversed(e.__traceback__.tb_next):
        lines.append(f"File {tb.tb_frame.f_code.co_filename}, line {tb.tb_lineno}, in {tb.tb_frame.f_code.co_name}")
        if tb.tb_next is None or len(lines) >= max_level:
            break
    path = ""
    for frame in reversed(e.__traceback__.tb_frame.f_back):
        path += f"{frame.f_code.co_name}, "
        if len(path) >= max_path_level:
            break
    path += f"{e.__traceback__.tb_frame.f_code.co_name}"
    lines.append(f"Path: {path}")
    return "\n".join(lines)

