def normalize_args(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single interfaces. Anything but individual interfaces or implements specs will be expanded.
    :param sequence: A sequence of interfaces or implementations
    :param output: The output object or sequence
    :return: The normalized argument sequence
    """
    if output is None:
        output = []
    for i in range(len(sequence)):
        item = sequence[i]
        if isinstance(item, Declaration):
            output.append(item)
        elif isinstance(item, tuple):
            output.extend(item)
