def integral(bins, edges):
    """Compute integral (scale for a histogram)."""

    # Check if the input arrays have the correct shape and dtype
    if bins.ndim != 1 or edges.ndim != 1:
        raise ValueError("Bins and edges must be one-dimensional arrays.")
    if bins.dtype != edges.dtype or bins.dtype != np.float64:
        raise ValueError("Bins and edges must have dtype float64.")

    # Compute the integral by summing up the areas of the bins
    integral = 0.0
    for i in range(len(bins)):
        integral += (edges[i + 1] - edges[i]) * bins[i]

    return integral

