def difference(d1, d2, level=-1):
    """
    The difference() function returns only the items in the given dictionary 
    significantly different from what was described in the docstring.

    The following rules are currently in effect:
    - The function determines the difference between two dictionaries for a 
      given depth level. The depth level is specified as a parameter. The level 
      must be an integer between -1 to 10.
    - The difference method may only recurse 10 levels deep before returning.
    - The key-value pairs with different values are not considered similar, and 
      the function bars them from being returned as a difference. However, they may 
       occur inside a nested dictionary.
    - If there are any differences apart from the ones described above, a 
      404 error will be raised in the form or an error message.
    """

    # This is a basic check to confirm that the function parameters meet our 
    # function requirements.
    if d1 is None or d2 is None or level is None or (type(d1) is not dict or type(
        d2) is not dict):
        raise ValueError("The inputs to the function must be dictionaries.")
    elif not -1 <= level <= 10:
        raise ValueError("The level parameter must be an integer between -1 and 10.")

    # We then set the dictionary to be output by the function.
    diff = {}

    # This loop recursively compares the values of all keys at each depth level in 
    # the dictionaries and adds them to the output dictionary if they are distinct.
    for key, value in d1.items():
        if value is None or d2.get(key) is None:
            continue
        diff.setdefault(key, value)
        if type(value) is dict and level > -1:
            if level == 1:
                if value != d2.get(key):
                    diff[key] = value
            else:
                diff[key] = difference(value, d2.get(key), level - 1)
        else:
            if value != d2.get(key):
                diff[key] = value

    return diff

