def validate_key(key):
    import re
    key_regex = re.compile(r"^[a-zA-Z0-9_-]{2,32}$")
    if not key_regex.match(key):
        raise ValidationError("Invalid key: " + key)
    return key

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generates a partial observer schema from part of a Kubernetes resource.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema
    """
    if first_level:
        observer_schema = {
            "identifying_fields": {
                "name": manifest_dict["metadata"]["name"],
                "namespace": manifest_dict["metadata"]["namespace"],
                "uid": manifest_dict["metadata"]["uid"],
            }
        }
    else:
        observer_schema = {}

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item))
                else:
                    new_list.append(None)
            observer_schema[key] = new_list
        else:
            observer_schema[key] = None

    return observer_schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    # Initialize an empty dictionary to store the generated partial observer schema
    partial_observer_schema = {}

    # Check if the input dictionary is none or empty
    if manifest_dict is None or len(manifest_dict) == 0:
        return partial_observer_schema

    # Iterate over all keys and values in the input dictionary
    for key, value in manifest_dict.items():
        # If the value is a list or a dictionary, recursively call this function
        # to generate the partial observer schema for that value
        if isinstance(value, list) or isinstance(value, dict):
            partial_observer_schema[key] = generate_default_observer_schema_dict(value, first_level=False)
        # If the value is not a list or a dictionary, replace it with None and add the key to the partial observer schema
        else:
            partial_observer_schema[key] = None

    # If this is the first level dictionary (i.e. the complete observer schema for a resource),
    # copy the identifying fields from the manifest file
    if first_level:
        partial_observer_schema["kind"] = manifest_dict["kind"]
        partial_observer_schema["apiVersion"] = manifest_dict["apiVersion"]

    return partial_observer_schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    result = {}
    for k, v in manifest_dict.items():
        if isinstance(v, (dict, list)):
            result[k] = generate_default_observer_schema_dict(v, first_level=first_level)
        else:
            result[k] = None
    if first_level:
        result["metadata"] = {
            "name": manifest_dict["metadata"]["name"],
            "labels": manifest_dict["metadata"]["labels"],
        }
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    new_dict = {}
    for key, value in manifest_dict.items():
        if isinstance(value, (list, dict)):
            new_dict[key] = generate_default_observer_schema_dict(value)
        else:
