def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for index, field in enumerate(observer_schema):
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[index]
        else:
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], observer_schema[field], response[index])

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i in range(len(response)):
        last_applied_manifest[i] = {}
        for key, value in response[i].items():
            # If key is present in last_applied_manifest, update its value
            if key in last_applied_manifest[i]:
                last_applied_manifest[i][key] = value
            # Else, initialize the key with the default value from the schema
            else:
                for schema_key, schema_value in observer_schema[key].items():
                    if schema_key == "type":
                        last_applied_manifest[i][key] = schema_value["default"]
    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    if not last_applied_manifest:
        return response

    for resp_obj in response:
        resp_obj_type = type(resp_obj)
        for obs_field in observer_schema:
            obs_field_name = obs_field['name']
            obs_field_type = obs_field['type']
            last_applied_manifest_copy = None
            if resp_obj_type == dict:
                if obs_field_name in resp_obj:
                    resp_obj_val = resp_obj[obs_field_name]
                    last_applied_manifest_copy = resp_obj_val
                else:
                    last_applied_manifest_copy = obs_field.get('default')
            elif resp_obj_type == list:
                if obs_field_name in resp_obj:
                    resp_obj_val = resp_obj[obs_field_name]
                    if isinstance(resp_obj_val, list):
                        last_applied_manifest_copy = resp_obj_val
                    else:
                        last_applied_manifest_copy = [resp_obj_val]
                else:
                    last_applied_manifest_copy = obs_field.get('default')
            update_last_applied_manifest_list_from_resp(last_applied_manifest_copy, obs_field.get('child_schema'), resp_obj_val)
            if last_applied_manifest_copy:
                last_applied_manifest[obs_field_name] = last_applied_manifest_copy

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for field in response:
        if field not in last_applied_manifest:
            last_applied_manifest[field] = None
        elif isinstance(last_applied_manifest[field], list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_schema, response[field])
        elif isinstance(last_applied_manifest[field], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema, response[field])

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in response:
            raise KeyError(f"Observed field {field} is not present in the Kubernetes response")
        if isinstance(response[field], dict):
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        else:
            last_applied_manifest[field] = response[field]
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, details in observer_schema.items():
        if field not in last_applied_manifest:
            last_applied_manifest[field] = details.get("default", {})
        if details.get("type") == "dict":
            if field not in response:
                last_applied_manifest[field] = {}
            else:
                response_value = response[field]
                if isinstance(response_value, dict):
                    last_applied_manifest[field] = update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[field], details, response_value
                    )
                else:
                    raise KeyError("Expected a dict for field '{}', but got '{}' instead".format(
                        field, type(response_value)
                    ))
        elif details.get("type") == "list":
            if field not in response:
                last_applied_manifest[field] = []
            else:
                response_value = response[field]
                if isinstance(response_value, list):
                    last_applied_manifest[field] = update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[field], details, response_value
                    )
                else:
                    raise KeyError("Expected a list for field '{}', but got '{}' instead".format(
                        field, type(response_value)
                    ))
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, schema in observer_schema.items():
        # If the field is not present in the response, raise a KeyError
        if field not in response:
            raise KeyError(f"The {field} field is not present in the response")

        # If the field is a dictionary, update the nested last_applied_manifest
        # recursively
        if schema["type"] == "object":
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], schema, response[field])

        # If the field is a list, update the nested last_applied_manifest
        # recursively
        elif schema["type"] == "array":
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field], schema, response[field])

        # Otherwise, initialize the field if it is not yet present in last_applied_manifest
        else:
            if field not in last_applied_manifest:
                last_applied_manifest[field] = response[field]

def generate_default_observer_schema(app):
    from krake.data.observer import ObserverSpec

    # Get the default observer schema for each resource type in the application's spec
    default_observer_schemas = {
        resource_type: ObserverSpec.get_default_observer_schema(resource_type)
        for resource_type in app.spec.manifest.keys()
        if resource_type not in app.spec.observer_schemas
    }

    # Use the default observer schema for each resource type to create a dictionary of
    # custom observer schema objects
    custom_observer_schemas = {
        resource_type: ObserverSpec.from_dict(
            default_observer_schema,
            **app.spec.observer_schemas.get(resource_type, {})
        )
        for resource_type, default_observer_schema in default_observer_schemas.items()
    }

    return custom_observer_schemas

def generate_default_observer_schema(app):
    default_observer_schema = {}

    for resource in app.spec.manifest:
        if resource.observer_schema is None:
            default_observer_schema[resource.type] = generate_default_observer_schema_for_resource(resource)

    return default_observer_schema

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes
    :param params: The set of in-style parameters.
    :type params: dict or list
    :return: A tuple containing the formatted SQL query and the set of converted out-style parameters.
    :rtype: tuple
    """

    # Validate inputs
    if not isinstance(sql, (str, bytes)):
        raise TypeError("'sql' must be a str or bytes")
    if not isinstance(params, (Mapping, Sequence)):
        raise TypeError("'params' must be a Mapping or Sequence")

    # Convert in-style parameters to out-style parameters
    out_params = {}
    if isinstance(params, Mapping):
        for key, value in params.items():
            if not isinstance(key, (str, int)):
                raise TypeError(f"'params' keys must be str or int, not {type(key)}")
            out_params[key] = value
    elif isinstance(params, Sequence):
        for i, value in enumerate(params):
            out_params[i + 1] = value

    # Replace in-style parameters with out-style parameters in the SQL query
    if isinstance(sql, str):
        for param in iterkeys(params):
            sql = sql.replace("?" + str(param), ":%s" % param)
    else:
        for param in iterkeys(params):
            sql = sql.replace(bytes([1]), b"%s".encode())

    return (sql, out_params)

def format(sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
    :class:`list`).
    """

    # Step 1: Check if the parameters are properly formatted
    if not isinstance(params, (dict, list)):
        raise TypeError("'params' must be a dictionary or a list")

    if isinstance(params, dict):
        if not all(isinstance(key, (str, int)) for key in params.keys()):
            raise TypeError("'params' keys must be strings or integers")

    if isinstance(params, dict):
        if not all(isinstance(value, (str, int)) for value in params.values()):
            raise TypeError("'params' values must be strings or integers")

    # Step 2: Convert the in-style parameters to out-style parameters
    if isinstance(params, dict):
        params = {"{" + key + "}": value for key, value in params.items()}

    if isinstance(params, list):
        params = [":p" + str(index + 1) for index, value in enumerate(params)]

    # Step 3: Replace the in-style parameters in the SQL query
    for parameter in params:
        sql = sql.replace(parameter, "", 1)

    return (sql, params)

def formatmany(sql, many_params):
    # Step 1: Check for valid inputs
    if not sql:
        raise ValueError("SQL query cannot be empty")
    if not many_params:
        raise ValueError("At least one set of in-style parameters must be provided")

    # Step 2: Convert multiple sets of in-style parameters to out-style parameters
    out_params = []
    for params in many_params:
        if isinstance(params, dict):
            out_params.append(dict(zip(params.keys(), params.values())))
        elif isinstance(params, (list, tuple)):
            out_params.append(list(zip(params)))
        else:
            raise ValueError("In-style parameters must be a dict or a list")

    # Step 3: Convert SQL query to use out-style parameters
    sql = sql.replace(SQLParams.in_style, SQLParams.out_style)

    # Step 4: Return formatted SQL query and converted out-style parameters
    return sql, out_params

