def check_digests_present_and_used(manifest_files, digests_used):
    for manifest_file in manifest_files:
        if digests_used.get(manifest_file) is not None:
            for digest_name in digests_used[manifest_file]:
                if digest_name not in manifest_file['digests']:
                    raise ValueError(f"Digest {digest_name} in manifest file {manifest_file} is not present.")

        for digest_name, digest_value in manifest_file['digests'].items():
            if digest_name not in digests_used:
                raise ValueError(f"Digest {digest_name} in manifest file {manifest_file} is not used.")
    return

def check_digests_present_and_used(manifest_files, digests_used):
    for manifest_file in manifest_files:
        if "digests" not in manifest_file:
            raise ValueError("Manifest file does not contain 'digests' attribute.")
        for digest_name in manifest_file["digests"].keys():
            if digest_name not in digests_used:
                raise ValueError(f"Digest {digest_name} is not used in the manifest.")
            elif manifest_file["digests"][digest_name] != digests_used[digest_name]:
                raise ValueError(f"Digest {digest_name} is used with a different value in the manifest.")
    return True

def validate_as_prior_version(self: InventoryValidator, prior: InventoryValidator):
    """
    Check that prior is a valid prior version of the current inventory object.

    :param prior: a prior InventoryValidator instance
    :return: True if the prior version is valid, False otherwise
    """
    try:
        self_filename = self.filename
        prior_filename = prior.filename
        if self_filename != prior_filename:
            raise ValueError("Prior filename does not match current inventory")
        if self _version != prior._version:
            raise ValueError("Prior version does not match current inventory")
        if self._archives != prior._archives:
            raise ValueError("Prior archives do not match current inventory")
        if self._templates != prior._templates:
            raise ValueError("Prior templates do not match current inventory")
        return True
    except AttributeError as e:
        raise ValueError(f"Invalid prior version: {e}")
    except (KeyError, TypeError) as e:
        raise ValueError(f"Invalid prior version: {e}")

def validate_as_prior_version(self, prior):
    if prior is None or not isinstance(prior, InventoryValidator):
        raise ValueError("Invalid prior inventory")
    if self.inventory_time < prior.inventory_time:
        raise ValueError("prior inventory time is not valid")
    if self.items != prior.items:
        raise ValueError("Items not consistent with prior inventory")
    if self.tags != prior.tags:
        raise ValueError("Tags not consistent with prior inventory")
    for item in self.items:
        if item not in prior.items:
            raise ValueError(f"Item {item} not in prior inventory")
    for tag in self.tags:
        if tag not in prior.tags:
            raise ValueError(f"Tag {tag} not in prior inventory")
    return True

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise ValueError("prior must be an InventoryValidator instance")
    if self.version != prior.version + 1:
        raise ValueError("prior version is not one less than current version")
    if self.item_count != prior.item_count:
        raise ValueError("item count has changed since prior version")
    for item_id, item in self.items.items():
        if item_id not in prior.items or item != prior.items[item_id]:
            raise ValueError("item has changed since prior version")

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for state in inventory.get_states(version):
        for content_file in state.get_content_files():
            logical_path_map.setdefault(content_file.get_logical_path(), set()).add(content_file)
    return logical_path_map

def get_logical_path_map(inventory, version):
    # Define a empty dictionary to store the logical path map
    logical_path_map = {}

    # Loop through each file in the inventory
    for file in inventory:
        # Check if the file belongs to this version
        if file["version"] == version:
            # Extract the logical path from the file
            logical_path = file["logical_path"]

            # Append the file to the set of content files for this logical path
            logical_path_map.setdefault(logical_path, set()).add(file)

    # Return the logical path map
