def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    logical_path_map = {}

    for file_path in inventory:
        # yields the tuple (logical_path, list_of_values)
        logical_path, list_of_values = parse_logical_path(file_path)

        if logical_path in logical_path_map:
            # add values to existing keys in the map
            logical_path_map[logical_path].update(list_of_values)
        else:
            # create new key in the map for this logical path
            logical_path_map[logical_path] = set(list_of_values)

    # filter out empty sets and delete duplicate entries
    for logical_path, content_files in list(logical_path_map.items()):
        if not content_files:
            logical_path_map.pop(logical_path)
        else:
            content_files.discard(None)
            if len(content_files) > 1:
                logical_path_map[logical_path] = sorted(list(content_files))

    return logical_path_map

