def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    try:
        # Check if the fixity block is present in the inventory
        if not fixity:
            raise ValueError("No fixity block found in inventory")

        # Check if the fixity block is a list
        if not isinstance(fixity, list):
            raise ValueError("Fixity block is not a list")

        # Check if each element in the fixity block is a dictionary
        for element in fixity:
            if not isinstance(element, dict):
                raise ValueError("Element in fixity block is not a dictionary")

        # Check if each dictionary in the fixity block has the required keys
        for element in fixity:
            if not all(key in element for key in ["file", "algorithm", "digest"]):
                raise ValueError("Dictionary in fixity block is missing required key")

        # Check if each file listed in the fixity block is in the manifest
        for element in fixity:
            if element["file"] not in manifest_files:
                raise ValueError(f"File {element['file']} is not in the manifest")

        # If all checks pass, return True
        return True

    except ValueError as e:
        # If any of the checks fail, return False
        return False

    except Exception as e:
        # If any other exception is raised, re-raise it
        raise e

def validate_fixity(self, fixity, manifest_files):
    # Check if the fixity block is well-formed
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if "files" not in fixity:
        raise ValueError("Fixity block must have a 'files' key")
    if not isinstance(fixity["files"], list):
        raise ValueError("Fixity block 'files' key must be a list")

    # Check if all files in the manifest are referenced in the fixity block
    for manifest_file in manifest_files:
        if manifest_file not in fixity["files"]:
            raise ValueError(f"{manifest_file} is not referenced in the fixity block")

    # Check if all files referenced in the fixity block exist
    for file in fixity["files"]:
