def pretty(self, indent=0, debug=False):
    if debug:
        print(f"Pretty printing {self} with indent {indent}")
    indent_str = "  " * indent
    result = f"{indent_str}{self.__class__.__name__}("
    for attr, value in self.__dict__.items():
        if isinstance(value, Enum):
            result += f"\n{indent_str}  {attr}: {value.name}"
        elif isinstance(value, list):
            result += f"\n{indent_str}  {attr}:"
            for item in value:
                if isinstance(item, Enum):
                    result += f"\n{indent_str}    - {item.name}"
                else:
                    result += f"\n{indent_str}    - {item}"
        else:
            result += f"\n{indent_str}  {attr}: {value}"
    result += "\n)"
    return result

