def absorb(self, args):
    """
    This method takes in a sequence of expressions and returns a list of expressions
    applying absorption and negative absorption.
    """
    new_list = []
    for i in range(len(args)):
        if args[i] not in new_list:
            new_list.append(args[i])
        elif "|" not in args[i] and "&" not in args[i]:
            new_list.append("({})".format(args[i]))
    return new_list

def absorb(self, args):
        result = []
        for i in args:
            if type(i) == Expression:
                if i.value == "|" or i.value == "&":
                    result.append(Expression(i.value))
                else:
                    result.append(Expression(i.value + " " + i.value[::-1]))
            else:
                result.append(Expression(i))
        return result

def absorb(self, args):
    result = []
    for i, _ in enumerate(args):
        arg = args[i]
        if i % 2 == 0:
            # Absorption
            if arg in result:
                result[i] = args[i]
            else:
                result.append(args[i])
        else:
            # Negative absorption
            if arg in result:
                result[i] = args[i-1] & args[i]
            else:
                result.append(args[i-1] & args[i])
    return result

def absorb(args):
    new_args = []
    for arg in args:
        if "|" in arg:
            new_args.append(arg.replace("|", ""))
        else:
            new_args.append("~" + arg)
    return new_args

