def normalized(self):
    # Calculate the number of days and hours in the relativedelta
    days = self.days % 1 + self.days // 1
    hours = self.hours % 1 + self.hours // 1

    # If the number of hours is greater than 24, round up the number of days
    if hours >= 24:
        days += 1
        hours -= 24

    # Create a new relativedelta object with the normalized days and hours
    return relativedelta(days=days, hours=hours)

