def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    # Check if the input is valid
    if not isinstance(commands, (list, tuple)):
        raise ValueError("Commands must be a list or tuple")
    if not isinstance(args, (list, tuple)):
        raise ValueError("Arguments must be a list or tuple")
    if not isinstance(cwd, str) and cwd is not None:
        raise ValueError("Working directory must be a string or None")
    if not isinstance(verbose, bool):
        raise ValueError("Verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise ValueError("Hide stderr must be a boolean")
    if not isinstance(env, dict) and env is not None:
        raise ValueError("Environment must be a dictionary or None")

    # Join the commands and arguments to create the full command
    command_list = []
    for command in commands:
        command_list.append(command)
    for arg in args:
        command_list.append(arg)
    full_command = " ".join(command_list)

    # Run the command
    if verbose:
        print(f"Running command: {full_command}")
    result = subprocess.run(full_command, shell=True, cwd=cwd, env=env)

    # Check the result
    if result.returncode != 0:
        if hide_stderr:
            raise subprocess.CalledProcessError(
                result.returncode, full_command, output=None
            )
        else:
            raise subprocess.CalledProcessError(
                result.returncode, full_command, output=result.stderr
            )

    # Return the result
    return result.stdout

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):

    # Validate input
    if not commands:
        raise ValueError("No commands provided")
    if not args:
        raise ValueError("No arguments provided")

    # Set up environment variables
    if env is None:
        env = {}

    # Set up process
    process = subprocess.Popen(
        args,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        cwd=cwd,
    )

    # Run command
    output = process.communicate()[0].decode().strip()

    # Handle errors
    if verbose and process.returncode != 0:
        print(f"Command returned non-zero exit status: {process.returncode}")
        if hide_stderr:
            print(f"Command stderr: {process.stderr}")
        else:
            print(f"Command stdout: {process.stdout}")

    # Return output
    return output

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):

    # Check if the input is valid
    if not isinstance(commands, list):
        raise ValueError("The 'commands' argument must be a list.")
    elif not all(isinstance(command, str) for command in commands):
        raise ValueError("The 'commands' list must contain only strings.")

    if args is None:
        args = []
    elif not isinstance(args, list):
        raise ValueError("The 'args' argument must be a list.")

    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("The 'cwd' argument must be a string or None.")

    if verbose is not None and not isinstance(verbose, bool):
        raise ValueError("The 'verbose' argument must be a boolean or None.")

    if hide_stderr is not None and not isinstance(hide_stderr, bool):
        raise ValueError("The 'hide_stderr' argument must be a boolean or None.")

    if env is not None and not isinstance(env, dict):
        raise ValueError("The 'env' argument must be a dictionary or None.")

    # Set up the subprocess call
    command = " ".join(commands)
    call_kwargs = {"args": args, "cwd": cwd, "env": env}
    if verbose:
        call_kwargs["stdout"] = sys.stdout
    elif hide_stderr:
        call_kwargs["stderr"] = open(os.devnull, "w")
    else:
        call_kwargs["stderr"] = sys.stderr

    try:
        subprocess.check_call(command, **call_kwargs)
    except subprocess.CalledProcessError as e:
        sys.exit(e.returncode)

    return 0

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    # Initialize a list to store the status codes of the commands
    status_codes = []

    # Iterate over the list of commands
    for command in commands:
        # If the current command is a string, wrap it in a list
        if isinstance(command, str):
            command = [command]

        # If a current working directory is provided, use it as the working directory for the command
        if cwd is not None:
            command = ['cd', cwd, '&&', command]

        # If the output of the command needs to be hidden, use a subprocess with a null output file
        if hide_stderr:
            command = ['/bin/bash', '-c', ' '.join(command), '>/dev/null']

        # If environment variables are provided, use them for the subprocess
        if env is not None:
            command = ['env'] + [f'{k}={v}' for k, v in env.items()] + command

        # If the command is a list of strings, execute the command using subprocess
        if isinstance(command, list):
            # If the output is to be verbose, print the command before executing it
            if verbose:
                print(' '.join(command))

            # Execute the command using subprocess, capturing the output and status code
            output, status_code = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT).communicate()

            # Add the status code to the list of status codes
            status_codes.append(status_code)

    # If the output of the command needs to be verbose, print the output of each command before returning it
    if verbose:
        for command, status_code in zip(commands, status_codes):
            print(command)
            print(status_code)

    # Return the status codes of the commands
    return status_codes

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    import subprocess
    import sys

    # Handle invalid inputs
    if not commands:
        raise ValueError("No commands specified")
    if not isinstance(commands, list):
        commands = [commands]

    # Create command list
    command_list = [c for c in commands]
    if args:
        for arg in args:
            command_list += [arg]

    # Handle environment variables
    if env:
        if not isinstance(env, dict):
            raise TypeError("Expected dict for env variable, got {}".format(type(env)))
        env_vars = []
        for k, v in env.items():
            env_vars += ["{}={}".format(k, v)]
        command_list += ["env"] + env_vars

    # Handle working directory
    if cwd:
        command_list += ["cd", cwd, ";"]

    # Handle verbose mode
    if verbose:
        command_list += ["verbose", ";"]

    # Handle hide_stderr
    if hide_stderr:
        command_list += ["2>/dev/null", ";"]

    # Run command
    try:
        subprocess.run(command_list, check=True)
    except subprocess.CalledProcessError as e:
        # Handle error
        sys.exit(e.returncode)

