    Args:
        validate_objects (bool, optional): Whether to validate the objects in the hierarchy. Defaults to True.
        check_digests (bool, optional): Whether to check the digests of the objects in the hierarchy. Defaults to True.
        show_warnings (bool, optional): Whether to show warnings if there are any issues with the objects in the hierarchy. Defaults to False.

    Returns:
        num_objects (int): The total number of objects in the hierarchy.
        good_objects (int): The number of objects that were found to be valid.

    Raises:
        ValueError: If `validate_objects` or `check_digests` is not a boolean value.
        RuntimeError: If there is a problem with the hierarchy or the validation process.
    """

    if not isinstance(validate_objects, bool):
        raise ValueError("`validate_objects` must be a boolean value")
    if not isinstance(check_digests, bool):
        raise ValueError("`check_digests` must be a boolean value")

    # Initialize variables
    num_objects = 0
    good_objects = 0

    # Iterate through the hierarchy
    for obj in self.iter_hierarchy():
        num_objects += 1

        if validate_objects:
            if not obj.validate():
                if show_warnings:
                    print(f"Warning: Object {num_objects} in the hierarchy is not valid")
            else:
                good_objects += 1

        if check_digests:
            if obj.digest != obj.recalculate_digest():
                if show_warnings:
                    print(f"Warning: Digest of object {num_objects} in the hierarchy does not match")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    if validate_objects:
        # Check objects
        for obj in self.objects:
            num_objects += 1
            if check_digests:
                # Check object digest
                if not obj.check_digest():
                    if show_warnings:
                        print(f"WARNING: invalid object digest for {obj}")
                    continue
            if obj.is_good():
                good_objects += 1

    # Check storage hierarchy
    if self.parent:
        if not self.parent.validate_hierarchy(validate_objects, check_digests, show_warnings):
            if show_warnings:
                print(f"WARNING: invalid parent storage hierarchy for {self}")

    return num_objects, good_objects

def next_version(version):
    if version.isdigit():
        major, minor, patch = version.split('.')
        patch = int(patch) + 1
        if patch == 10:
            minor = str(int(minor) + 1)
            patch = 0
        if minor.startswith('0'):
            major = str(int(major) + 1)
        return f'{major}.{minor}.{patch}'
    else:
        raise ValueError('Invalid version format: {version}')

def next_version(version):
    version_ints = [int(digit) for digit in version.split(".")]
    last_digit = version_ints[-1]

    if last_digit == 9:
        # Handle 99999 case
        last_digit = 0
        for i in range(len(version_ints) - 2, -1, -1):
            if version_ints[i] != 9:
                break
            last_digit = 1

    else:
        last_digit += 1

    version_ints[-1] = last_digit
    return ".".join(map(str, version_ints))

