def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        key, value = node
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            result.append((key, deep_merge_mapping_nodes([value])))
        else:
            result.append(node)
    return result

def deep_merge_nodes(nodes):
    result = []
    temp = {}

    for key, value in nodes:
        if value.tag == 'tag:yaml.org,2002:map':
            for scalar, mapped_value in value.value:
                if scalar.value not in temp:
                    temp[scalar.value] = mapped_value
                else:
                    if mapped_value.tag != temp[scalar.value].tag:
                        temp[scalar.value] = mapped_value

    for key, value in nodes:
        if value.tag == 'tag:yaml.org,2002:str':
            result.append((key, temp[value.value]))

    return result

