    result = []
    for node in nodes:
        key, value = node
        if value.tag != 'tag:yaml.org,2002:map':
            continue
        for subkey, subvalue in value.value:
            if subvalue.tag == 'tag:yaml.org,2002:int' or subvalue.tag == 'tag:yaml.org,2002:str':
                continue
            elif subvalue.tag == 'tag:yaml.org,2002:map':
                for inner_node in deep_merge_nodes([(subkey, subvalue)]):
                    result.append(inner_node)
