def deep_merge_nodes(nodes):
    result = []

    for node in nodes:
        key, value = node
        current = result
        keys = key.value.split(".")
        for i, key in enumerate(keys):
            for child in current:
                if child[0].value == key:
                    if isinstance(child[1], ruamel.yaml.nodes.MappingNode):
                        current = child[1].value
                    else:
                        current.pop(current.index(child))
                        current.append((key, value))
                        break
            else:
                # current doesn't contain a child key
                current.append((key, value))
                break

    return result

