def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.
    """
    size_map = {
        "K": 1000,
        "M": 1000000,
        "G": 1000000000,
        "T": 1000000000000,
    }

    unit = size[-1]
    value = float(size[:-1])

    if unit not in size_map:
        raise ValueError(f"Invalid unit: {unit}")

    return int(value * size_map[unit])

def size_to_bytes(size: str) -> int:
    """
    Convert human-readable file size to bytes.

    See docstring for details.
    """

    size = size.upper()
    suffix = size[-2:]
    value = size[:-2]
    try:
        value = float(value)
    except ValueError:
        raise InvalidFileSizeError(f"Invalid file size {size}")

    if suffix == 'KB':
        return int(value * 1000)
    elif suffix == 'MB':
        return int(value * 1000 * 1000)
    elif suffix == 'GB':
        return int(value * 1000 * 1000 * 1000)
    elif suffix == 'TB':
        return int(value * 1000 * 1000 * 1000 * 1000)
    else:
        raise InvalidFileSizeError(f"Invalid file size suffix {suffix}")

def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.
    Resulting value is an approximation as input value is in most case rounded.
    Args:
        size: A string representing a human readable file size (eg: '500K')
    Returns:
        A decimal representation of file size
        Examples::
            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    units = {'b': 1, 'kb': 1000, 'mb': 1000000, 'gb': 1000000000}
    size = size.lower()
    if any(i.isdigit() for i in size):
        return int(float(size.replace(',', '')))
    else:
        for i in units:
            if i in size:
                return int(float(size.replace(i, '')) * units[i])
    raise Exception('Invalid size')

