def vertex3tuple(vertices):
    if len(vertices) < 3:
        raise ValueError("At least three vertices required.")
    result = []
    for i in range(len(vertices) - 1):
        result.append((vertices[i], vertices[i+1]))
        result.append((vertices[i+1], vertices[i+2]))
    result.append((vertices[-1], vertices[0]))
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int) or not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise TypeError("inputs must be of type int, list[str], and list[str]")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be of type int")

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None:
        result = result.rjust(padding)

    return result

