def get_repo_archive(url: str, destination_path: Path) -> Path:
    try:
        r = requests.get(url)
    except requests.exceptions.RequestException as e:
        raise ValueError(f"Error when requesting URL {url}: {e}")

    if r.status_code != 200:
        raise ValueError(f"Get request returned status {r.status_code} for URL {url}")

    archive_path = destination_path / url.split("/")[-1]
    with open(archive_path, "wb") as f:
        for chunk in r.iter_content(1024):
            f.write(chunk)

    try:
        with tarfile.open(archive_path, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except tarfile.TarError as e:
        raise ValueError(f"Error when extracting tar.gz: {e}")

    return destination_path

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    result = {}
    for key, value in item.items():
        if re.search(r'\*+\.\w+', key):
            key = re.sub(r'\*+\.\w+', r'(\w+)', key)
            result[key] = value
        else:
            result[key] = value
    return result

