    if platform == 'this':
        platform = shlex.get_platform()

    if platform == 1: # POSIX
        result = re.split(r'(\\)?(' + re.escape(shlex.WHITESPACE) + r')', s)
    elif platform == 0: # Windows/CMD
        result = re.split(r'(\\)?(\s|")', s)
