def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set[rdflib.Node]] = None) -> Set[rdflib.Node]:
    if not roots:
        roots = set()
    for subject, predicate, object in graph:
        if predicate == prop and subject in roots:
            continue
        if object in roots:
            roots.add(subject)
    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()
    for s, o in graph.subjects(prop, None):
        if s not in roots:
            roots.add(s)
            for triple in graph.triples((s, prop, None)):
                roots.update(find_roots(graph, triple.o, roots))
    return roots

