    # Check that the candidate defines all necessary methods
    for method in iface.getAllMethodDocs():
        if not hasattr(candidate, method.name):
            raise zope.interface.Invalid(f"The candidate does not define the '{method.name}' method.")

    # Check the signature of the methods
    for method in iface.getAllMethodDocs():
        method_obj = getattr(candidate, method.name)
        if not isinstance(method_obj, types.FunctionType):
            raise zope.interface.Invalid(f"The '{method.name}' method must be a function.")
        if method.arglist != method_obj.__code__.co_varnames:
            raise zope.interface.Invalid(f"The signature of the '{method.name}' method does not match the interface definition.")

    # Check that the candidate defines all necessary attributes
    for attr in iface.getAllAttributeDocs():
        if not hasattr(candidate, attr.name):
            raise zope.interface.Invalid(f"The candidate does not define the '{attr.name}' attribute.")

    # If we reach this point, everything passed the verification
    return True

