    """
    Determine the metaclass of a class by checking the hierarchy of its bases and an optional explicit `__metaclass__` argument.

    :param bases: the parent classes of the class being created
    :param explicit_mc: an optional explicit `__metaclass__` argument, which takes priority over the metaclass determination by the hierarchy of `bases`
    :return: the determined metaclass
    """
    if explicit_mc is not None:
        # Use explicit metaclass if provided
        return explicit_mc
    else:
        # Determine metaclass ourselves by traversing the hierarchy of bases
        if len(bases) == 1:
            # Single base, no need to traverse hierarchy
            return bases[0].__class__
        elif len(bases) > 1:
            # Multiple bases, traverse hierarchy
            for base in bases:
                if base.__class__ is type:
                    # Found the base that is a type, return its class
                    return base.__class__
            # No type base found, use the first base's class as the metaclass
            return bases[0].__class__
        else:
            # No bases, use the type class as the metaclass
            return type.__class__

