        if request.public_message_url:
            return "public_message"
        # Try private message
        elif request.private_message_url:
            return "private_message"
        # Check if this is a legacy payload
        elif request.legacy_payload:
            return "legacy_payload"
        else:
            return "unknown"
    except Exception as e:
        return "unknown"

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """

    try:
        # Try to decode the request as a Diaspora payload
        payload = json.loads(request.body)
        if "attachment" in payload and "diaspora_handle" in payload["attachment"]:
