def find_tags(text, replacer=None):
    # Initialize variables
    tags = set()
    replaced_text = text

    # Iterate over the characters in the text
    for i in range(len(text)):
        # Check if the current character is a left bracket (<)
        if text[i] == '<':
            # Check if the next character is a slash (/)
            if i + 1 < len(text) and text[i + 1] == '/':
                # Check if the third character after the left bracket is a word character
                if i + 3 < len(text) and text[i + 3].isalpha():
                    # Add the tag to the set of tags
                    tags.add(text[i + 3:i + 3])
            else:
                # Check if the next character is a word character
                if i + 1 < len(text) and text[i + 1].isalpha():
                    # Add the tag to the set of tags
                    tags.add(text[i + 1:i + 1])

    # If a replacer function was passed, use it to replace the tags in the text
    if replacer:
        for tag in tags:
            replaced_text = replaced_text.replace(tag, '{}'.format(replacer(tag)))

    # Return the set of tags and the replaced text
    return tags, replaced_text

