def get_nodeinfo_well_known_document(url, document_path=None):    
    """
    Generate a .well-known/nodeinfo document.

    See spec: https://nodeinfo.diaspora.software/

    :param url: The full base URL with protocol, ie https://example.com
    :param document_path: Custom .well-known/nodeinfo document path if supplied (optional)
    :return: dict
    """

    # Verify input URL
    try:
        parsed_url = urlparse(url)
        if not parsed_url.scheme or not parsed_url.netloc:
            raise ValueError("Invalid URL format")
    except ValueError as e:
        raise ValueError(f"Invalid URL format: {e}")

    # Build path for .well-known/nodeinfo document
    if document_path:
        if not document_path.startswith("/"):
            raise ValueError("Custom NodeInfo document path must start with '/'")
        if not document_path.endswith("/nodeinfo"):
            raise ValueError("Custom NodeInfo document path must end with '/nodeinfo'")
        well_known_path = document_path
    else:
        well_known_path = f"{parsed_url.scheme}://{parsed_url.netloc}/.well-known/nodeinfo"

    # Fetch .well-known/nodeinfo document
    try:
        response = requests.get(well_known_path)
        if response.status_code != 200:
            raise RuntimeError(f"Failed to fetch {well_known_path}: {response.status_code}")
    except requests.exceptions.RequestException as e:
        raise RuntimeError(f"Failed to fetch {well_known_path}: {e}")

    # Parse .well-known/nodeinfo document
    try:
        nodeinfo_doc = response.json()
    except json.decoder.JSONDecodeError as e:
        raise RuntimeError(f"Failed to parse {well_known_path} as JSON: {e}")

    return nodeinfo_doc

