def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        xrd = {"Subject": None, "Aliases": [], "Links": []}
        links = []
        for link in document.split("\n"):
            if link.startswith("<"):
                if link.endswith(">") and "/>" not in link:
                    xrd["Subject"] = link.strip("<").strip(">")
                else:
                    xrd["Aliases"].append(link.strip())
            elif link.startswith("Link:"):
                rel, href = link.split(";")
                rel = rel.strip()
                href = href.split(";")[0].strip()
                links.append({"rel": rel, "href": href})
        xrd["Links"] = links
        return xrd
    except Exception:
        raise Exception("Invalid Diaspora webfinger document")

