        "timeout": timeout,
        "method": method,
        *args,
        **kwargs,
    }

    # Make the request
    try:
        response = requests.request(**request_kwargs)
    except requests.RequestException as e:
        return None, e

    # Check the status code
    if response.status_code not in (200, 201):
        return None, response.status_code

    # Return the response
    return response.status_code, None

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        response = requests.post(url, data, timeout=timeout, method=method, *args, **kwargs)
        return (response.status_code, None)
    except Exception as e:
        return (None, e)

def dict_insert(dic, val, key, *keys):
    if not dic:
        raise ValueError("dic should not be empty")
    if not key:
        raise ValueError("key should not be empty")
    if not keys:
        raise ValueError("keys should not be empty")

    current_dict = dic
    for subkey in keys[:-1]:
        if not subkey in current_dict:
            raise KeyError(f"subkey {subkey} not found in the dictionary")
        current_dict = current_dict[subkey]

    current_dict[keys[-1]] = val

    return dic

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary"""
    # check if the given dictionary is valid
    if not isinstance(dic, dict):
        raise ValueError("dic must be a dictionary")
    # check if the key is a string
    if not isinstance(key, str):
        raise ValueError("key must be a string")
    # check if the value is valid
    if not isinstance(val, (str, int, float, bool)):
        raise ValueError("val must be a string, integer, float, or boolean")
    # check if the keys are valid
    for k in keys:
        if not isinstance(k, str):
            raise ValueError("all keys must be strings")
    # insert the value into the dictionary
    current = dic
    for k in keys:
        if k not in current:
            current[k] = {}
        current = current[k]
    current[key] = val

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file names in the specified directories.

    Args:
        settings_dirs (list): A list of settings directories.
        spec_option (str): The option for list files.

    Returns:
        list: A list of file names.
    """

    files = []

    for directory in settings_dirs:
        for root, dirs, files in os.walk(directory):
            if spec_option == "include":
                if files:
                    files_subset = list(files)
                else:
                    files_subset = None
            else:
                files_subset = None

            if files_subset:
                for file in files_subset:
                    files.append(os.path.join(root, file))

    return files

