    """Create a new IniType complex type
    """
    if not os.path.isdir(settings_dirs):
        raise ValueError("Path is not a valid directory")

    file_names = []
    for dirpath, dirnames, filenames in os.walk(settings_dirs):
        file_names.extend(filenames)

    ini_file_names = []
    for file_name in file_names:
        if file_name.endswith(".ini"):
            ini_file_names.append(file_name)

    return ini_file_names

