def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): The parser dictionary to modify.

    Raises:
        TypeError: If the input is not a dictionary.
        KeyError: If the 'include' key is missing from the dictionary.
        ValueError: If the value associated with the 'include' key is not a list.
    """
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dictionary")
    try:
        include_keys = parser_dict["include"]
    except KeyError:
        raise KeyError("missing 'include' key in parser_dict")
    if not isinstance(include_keys, list):
        raise ValueError("value associated with 'include' key must be a list")
    for filename in include_keys:
        if os.path.isfile(filename):
            with open(filename, "r") as f:
                parser_dict.update(json.load(f))
        else:
            raise FileNotFoundError(f"{filename} does not exist")
    return parser_dict

def _include_groups(self, parser_dict):
    try:
        include_dict = parser_dict.get("include")
        if include_dict is None:
            raise ValueError("Invalid input: 'include' directive not found in parser_dict.")
        for group in include_dict:
            group_dict = include_dict.get(group)
            if group_dict is None:
                raise ValueError(f"Invalid input: 'group' key not found in include_dict for group '{group}'.")
            group_type = include_dict.get("type")
            if group_type is None:
                raise ValueError(f"Invalid input: 'type' key not found in include_dict for group '{group}'.")
            group_format = include_dict.get("format")
            if group_format is None:
                raise ValueError(f"Invalid input: 'format' key not found in include_dict for group '{group}'.")
            group_options = include_dict.get("options")
            if group_options is None:
                raise ValueError(f"Invalid input: 'options' key not found in include_dict for group '{group}'.")
            group_directive = f"{group_type}({group_format})"
            for option in group_options:
                if option not in group_directive:
                    raise ValueError(f"Invalid input: option '{option}' not found in include_dict for group '{group}'.")
    except ValueError as e:
        raise ValueError(e) from None
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): Parser dictionary containing the include
            directives.

    Returns:
        None

    Raises:
        ValueError: If the 'include' directive is not defined.
        ValueError: If the 'include' directive has an invalid value.
    """
    if 'include' not in parser_dict:
        raise ValueError('Missing "include" directive')
    include_dict = parser_dict['include']
    if not isinstance(include_dict, dict):
        raise ValueError('Invalid value for "include" directive')
    for name, value in include_dict.items():
        try:
            if value not in self.params:
                self.params[name] = self.specs[value]
        except KeyError:
            raise ValueError(f'Invalid key {value} in "include" directive')

def get_spec_defaults(self):
    """
    Resolve the default values for the arguments from the specification and other sources.

    Returns:
    --------
    defaults (dict): A dictionary with the default arguments and their values.
    """

    # Build a dictionary of default values for all arguments
    defaults = {}
    for arg_name, arg_value in self.spec.get('defaults', {}).items():
        defaults[arg_name] = self.resolve_arg_default(arg_name, arg_value)

    # Handle any runtime issues that may arise during argument default value resolution
    try:
        for arg_name, arg_value in defaults.items():
            arg_value = self.cast_arg_value(arg_name, arg_value)

        return defaults
    except Exception as e:
        # Raise a custom exception that indicates a problem with the argument default values
        raise RuntimeException(f'Failed to resolve argument defaults: {e}') from e

