def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.

    :return: The resolved arguments.
    """
    # Step 1: Initialize an empty dictionary to store the resolved arguments
    resolved_args = {}

    # Step 2: Check if the spec is available, and if so, get the spec
    if hasattr(self, 'spec'):
        spec = self.spec
    else:
        raise ValueError("Spec not available.")

    # Step 3: Iterate over the arguments in the spec
    for arg_name, arg_info in spec.items():
        # Step 3a: Check if the argument has a default value
        if 'default' in arg_info:
            # Step 3a.1: Use the default value as the resolved value
            resolved_args[arg_name] = arg_info['default']
        else:
            # Step 3a.2: Check if there is a source for the argument
            if 'source' in arg_info:
                # Step 3a.2.1: Get the value from the named source
                resolved_args[arg_name] = self.get_value_from_source(arg_info['source'])
            else:
                # Step 3a.2.2: The argument has no default value and no source to fall back on, raise an error
                raise ValueError(f"Argument {arg_name} has no default value and no source to fall back on.")

    # Step 4: Return the resolved arguments
    return resolved_args

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary with all the argument values resolved from the spec and other sources.
    """
    # Step 1: Gather all the arguments and their default values from the spec
    arg_defaults = {}
    for arg in self.spec.args:
        if arg.default:
            arg_defaults[arg.name] = arg.default

    # Step 2: Override defaults with user-provided values from the request
    override_values = self.request.get("arguments", {})
    if override_values:
        for key, value in override_values.items():
            if key in arg_defaults:
                arg_defaults[key] = value

    # Step 3: Return the resolved defaults
    return arg_defaults

