    if not cli_args or not answer_file_args:
        raise ValueError("Either cli or answer file arguments must be provided")

    # Validate if both cli and answer file args are not empty dicts
    if not cli_args and not answer_file_args:
        raise ValueError("Either cli or answer file arguments must not be empty")

    # Validate if cli and answer file args have the same keys
    if set(cli_args.keys()) != set(answer_file_args.keys()):
        raise ValueError("Cli and answer file arguments must have the same keys")

    # Validate if cli and answer file args have the same types
    for key, value in cli_args.items():
        if type(value) != type(answer_file_args[key]):
            raise ValueError(f"Type mismatch for argument '{key}': {type(value)} != {type(answer_file_args[key])}")

    # Validate if cli and answer file args have the same values
    for key, value in cli_args.items():
        if value != answer_file_args[key]:
            raise ValueError(f"Value mismatch for argument '{key}': {value} != {answer_file_args[key]}")

    # Deprecated args are not included in the updated args
    deprecated_args = []
    for key, value in cli_args.items():
        if value in DEPRECATED_ARGS:
            deprecated_args.append(key)

    if deprecated_args:
