def _get_conditionally_required_args(command_name: str, options_spec: Dict[str, Dict[str, Any]], args: Dict[str, Any]) -> List[str]:
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """

    # Construct a mapping of option names to their corresponding condition functions
    option_required_when_map = {
        option_name: option_spec.get("required_when")
        for option_name, option_spec in options_spec.items()
    }

    # Get the current value of each required-when condition function
    current_values = {
        option_name: eval(required_when, globals(), args)
        for option_name, required_when in option_required_when_map.items()
    }

    # Find the matching option names
    matching_option_names = [
        option_name
        for option_name, required_when in option_required_when_map.items()
        if current_values[option_name]
    ]

    return matching_option_names

