def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    try:
        if not subcommand:
            raise ValueError("Subcommand cannot be empty")
        if not type_name:
            raise ValueError("Type name cannot be empty")
        if not option_name:
            raise ValueError("Option name cannot be empty")
        if not spec_option:
            raise ValueError("Spec option cannot be empty")

        return subcommand, type_name, option_name, spec_option
    except Exception as e:
        raise ValueError(f"Error creating complex argument type: {e}")

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """

    if spec_option is None:
        raise ValueError("Cannot create complex argument with no spec option")

    try:
        type_class = spec_option.type_class
    except AttributeError:
        raise ValueError("Spec option must have a type_class attribute")

    try:
        type_args = spec_option.type_args
    except AttributeError:
        raise ValueError("Spec option must have a type_args attribute")

    if type_name == "list":
        return list(type_class)

    elif type_name == "dict":
        if not type_args:
            raise ValueError("Spec option must have type_args for dict type")

        if len(type_args) != 2:
            raise ValueError("Spec option must have two type_args for dict type")

        return {type_args[0](key): type_args[1](value)
                    for key, value in spec_option.items()}

    elif type_name == "enum":
        if not type_args:
            raise ValueError("Spec option must have type_args for enum type")

        return type(type_name, type_args, {})()

    else:
        raise ValueError("Unrecognized complex type name")

def create_complex_argumet_type(subcommand, type_name, option_name,
                                              spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        # Check if the subcommand and type name are valid
        if subcommand not in ['list', 'create'] or type_name not in ['user', 'group']:
            raise ValueError("Invalid subcommand or type name")

        # Check if the option name and spec_option are valid
        if option_name not in spec_option or spec_option[option_name] is None:
            raise ValueError("Invalid option name or specification")

        # Build the complex argument type
        if subcommand == 'list':
            if type_name == 'user':
                return UserList(option_name, spec_option[option_name])
            elif type_name == 'group':
                return GroupList(option_name, spec_option[option_name])
        elif subcommand == 'create':
            if type_name == 'user':
                return UserCreate(option_name, spec_option[option_name])
            elif type_name == 'group':
                return GroupCreate(option_name, spec_option[option_name])
        else:
            raise ValueError("Invalid subcommand")
    except ValueError as e:
        logging.error(f"{e}")
        return None

def create_complex_argumet_type(subcommand, type_name, option_name, spec_option):
    if subcommand not in ("create", "update"):
        raise ValueError(f"Invalid subcommand: {subcommand}")
    if type_name not in ("map", "list"):
        raise ValueError(f"Invalid type name: {type_name}")
    if option_name == "":
        raise ValueError("Option name is required")
    if spec_option is None:
        raise ValueError("Spec option is required")

    if subcommand == "create":
        if type_name == "map":
            return ComplexMapType(option_name, spec_option)
        else:
            return ComplexListType(option_name, spec_option)
    else:
        if type_name == "map":
            return ComplexListType(option_name, spec_option)
        else:
            return ComplexMapType(option_name, spec_option)

def create_complex_argument_type(self, subcommand, type_name, option_name, spec_option):
