def get_nested_custom_and_control_args(args):
    """
    Split input arguments to control nested and custom.
    """
    control_args = {}
    nested_args = {}
    for arg in args:
        if arg.startswith("--control"):
            name = arg.replace("--control", "")
            control_args[name] = args[arg]
        elif arg.startswith("--nested"):
            name = arg.replace("--nested", "")
            nested_args[name] = args[arg]
        elif arg.startswith("--"):
            custom_args[arg] = args[arg]
    return custom_args, nested_args

def get_nested_custom_and_control_args(args):
    """
    Split input arguments to control nested and custom.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    # Split the input arguments into control and nested arguments.
    control_args = {
        arg: value for arg, value in args.items() if arg.startswith('--')
    }
    nested_args = {
        arg: value for arg, value in args.items() if arg not in control_args
    }

    # Handle potential invalid controls.
    if '--' in control_args:
        raise ValueError('Unexpected control argument')

    # Remove any nested arguments that are not allowed.
    disallowed_nested_args = {
        '--nested1', '--nested2'
    }
    nested_args = {
        arg: value for arg, value in nested_args.items()
        if arg not in disallowed_nested_args
    }

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        control_args = {}
        nested_args = {}
        for param, value in args.items():
            if param.startswith("control ") or param.startswith("nested "):
                # Check if param starts with "control" or "nested"
                control_args = self.check_params(control_args, param, value)
                nested_args = self.check_params(nested_args, param, value)
            else:
                # Custom arguments
                control_args["custom_" + param] = value
        return control_args, nested_args

    def check_params(self, dict, param, value):
        new_value = {"control": "control_args", "nested": "nested_args"}[param.split(" ")[1]:]
        dict.update({new_value: value})
        return dict

def get_nested_custom_and_control_args(args):
    control_args = {}
    nested_args = {}

    # Iterate through all input arguments
    for arg, val in args.items():
        # Check if the argument is a control argument
        if arg.startswith("control_arg"):
            control_args[arg] = val
        # Check if the argument is a nested argument
        elif arg.startswith("nested_arg"):
            nested_args[arg] = val
        # Check if the argument is a custom argument
        elif arg.startswith("custom_arg"):
            for nested_arg, nested_val in val.items():
                nested_args[f"{arg}_{nested_arg}"] = nested_val

    return control_args, nested_args

