    if extra_vars is None:
        extra_vars = []
    for var in extra_vars:
        if var not in vars_dict:
            vars_dict[var] = None
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend `vars_dict` with `extra-vars`
    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars:
        for var_name, var_value in extra_vars.items():
            if var_name not in vars_dict:
                vars_dict[var_name] = var_value

            else:
                if isinstance(vars_dict[var_name], list):
                    if isinstance(var_value, list):
                        vars_dict[var_name].extend(var_value)
                    else:
                        vars_dict[var_name].append(var_value)

                elif isinstance(vars_dict[var_name], dict):
                    if isinstance(var_value, dict):
                        merge_extra_vars(vars_dict[var_name], var_value)
                    else:
                        vars_dict[var_name].update({var_value})

                else:
                    merge_extra_vars(vars_dict, {var_name: var_value})

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
