    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Parses the CLI arguments and invokes ansible-playbook."""
    # Validate input parameters
    if not isinstance(ir_workspace, ir_field.Workspace):
        raise ValueError("ir_workspace must be an Infrared Workspace object")
    if not isinstance(ir_plugin, ir_field.Plugin):
        raise ValueError("ir_plugin must be an InfraredPlugin object")
    if not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a string")
    if verbose is not None and not isinstance(verbose, int):
        raise ValueError("verbose must be an integer or None")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("extra_vars must be a dict or None")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("ansible_args must be a dict or None")

    # Set up Ansible arguments
    args = []
    if verbose is not None:
        args.append("-" + str(verbose))
    if extra_vars is not None:
        for key, value in extra_vars.items():
            args.append("-e")
            args.append(f"{key}={value}")
    if ansible_args is not None:
        for key, value in ansible_args.items():
            args.append(key)
            args.append(value)

    # Run Ansible
    try:
        ansible_result = subprocess.run(["ansible-playbook", playbook_path] +
                                        args,
                                        timeout=1800)
        if ansible_result.returncode != 0:
            raise RuntimeError(ansible_result.stdout)
    except subprocess.TimeoutExpired:
        raise RuntimeError("Ansible execution timed out after 30 minutes")

    return ansible_result.returncode

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    # Check if the playbook path is valid
    if not os.path.exists(playbook_path):
        raise ValueError(f"Playbook at path '{playbook_path}' does not exist")

    # Check if the workspace is valid
    if not isinstance(ir_workspace, InfraredWorkspace):
        raise ValueError("Ir workspace must be an instance of InfraredWorkspace")

    # Check if the current plugin is valid
    if not isinstance(ir_plugin, InfraredPlugin):
        raise ValueError("Ir plugin must be an instance of InfraredPlugin")

    # Check if the ansible_args are valid
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("Ansible args must be a dictionary")

    # Check if the extra_vars are valid
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("Extra vars must be a dictionary")

    # Set the default values for the ansible-playbook args
    default_args = {
        "--inventory": "localhost,",
        "--connection": "local",
        "--module-path": os.path.join(os.getcwd(), "ansible", "playbooks"),
    }

    # Initialize the ansible-playbook command
    cmd = ["ansible-playbook", playbook_path]

    # Add the verbose level
    if verbose is not None:
        if verbose < 0 or verbose > 3:
            raise ValueError(f"Verbose level not supported: {verbose}")
        cmd.extend(["-" + "v" * verbose])

    # Add the extra vars
    if extra_vars is not None:
        for key, value in extra_vars.items():
            cmd.extend(["-e", f"{key}={value}"])

    # Add the ansible-playbook args
    if ansible_args is not None:
        for arg, value in ansible_args.items():
            cmd.extend([arg, value])

    # Set the command environment
    env = {
        "ANSIBLE_CONFIG": os.path.join(os.getcwd(), "ansible", "ansible.cfg")
    }

    # Run the ansible-playbook command
    result = subprocess.check_call(cmd, env=env, cwd=os.getcwd())

    # Return the result
    return result

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose, extra_vars=None, ansible_args=None):
    if verbose is not None and verbose not in range(0, 3):
        raise ValueError("Verbose must be a value from 0 to 2")

    if not playbook_path:
        raise ValueError("Playbook path is required")

    if extra_vars and not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dictionary")

    if ansible_args and not isinstance(ansible_args, dict):
        raise TypeError("ansible_args must be a dictionary")

    # construct the ansible-playbook command
    command = ["ansible-playbook"]

    if verbose is not None:
        command.extend(["-v", str(verbose)])

    if extra_vars:
        command.extend(["-e", json.dumps(extra_vars)])

    if ansible_args:
        for arg, value in ansible_args.items():
            command.extend([arg, str(value)])

    command.append(playbook_path)

    # run the ansible-playbook command in the appropriate workspace
    if ir_workspace.is_service:
        with ir_workspace.activate_service_context():
            ir_plugin.exec_command(command)
    else:
        with ir_workspace.activate_context():
            ir_plugin.exec_command(command)

