def _convert_non_cli_args(self, parser_name, values_dict):
    if not values_dict:
        return

    # Get the correct argument parser
    parser = self.get_argument_parser(parser_name)

    # Iterate over all the arguments and convert them to correct types
    for arg, value in values_dict.items():
        try:
            if parser.has_option(arg):
                # Get the argument type
                type_ = parser.get_option(arg).type
                # Convert the value to the correct type
                value_ = type_(value)
                # Update the value in the dictionary
                values_dict[arg] = value_
        except Exception as e:
            logging.error(f"Error converting argument {arg} with value {value} to correct type: {str(e)}")

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    try:
        with open(plugin_dir / "plugin.json", "r") as f:
            plugin_spec = json.load(f)
    except FileNotFoundError:
        raise FileNotFoundError(f"Plugin directory {plugin_dir} does not contain plugin.json file")
    flatten_dict = {}
    for key in plugin_spec:
        if isinstance(plugin_spec[key], dict):
            for subkey in plugin_spec[key]:
                flatten_dict[f"{key}.{subkey}"] = plugin_spec[key][subkey]
        else:
            flatten_dict[key] = plugin_spec[key]
    return flatten_dict

